# Surah Al-Jumu'a (chapter 62) — all ayat 1-11 (IDs 5178-5188)
SURAH = 62

ENTRIES = {
5178: (
"بسم اللہ الرّحْمٰن الرّحِیْم — اللہ کی تسبیح کرتا ہے جو آسمانوں میں ہے اور جو زمین میں ہے — بادشاہ قدوس غالب حکمت والا",
"""۱۔ تسبیح کا آغاز — یسبّح للہ ما في السماوات و ما في الأرض؛ الملک القدوس العزیز الحکیم۔
۲۔ ’’يُسَبِّحُ لِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ الْمَلِكُ الْقُدُّوسُ الْعَزِيزُ الْحَكِيمُ‘‘ — اللہ کی تسبیح کرتا ہے جو آسمانوں میں ہے اور جو زمین میں ہے — بادشاہ قدوس غالب حکمت والا — یعنی اللہ کی تسبیح کرتا ہے جو آسمانوں میں ہے اور جو زمین میں ہے بادشاہ قدوس غالب حکمت والا۔
۳۔ عملی سبق: ہر مخلوق اللہ کی تسبیح کرتی ہے؛ اللہ سے ڈرو۔"""
),
5179: (
"وہی ہے جس نے ان پڑھوں میں انہیں میں سے ایک رسول اٹھایا — جو ان پر اس کی آیات پڑھتا ہے اور انہیں پاک کرتا ہے اور انہیں کتاب اور حکمت سکھاتا ہے — اگرچہ وہ اس سے پہلے کھلی گمراہی میں تھے",
"""۱۔ محمد صلی اللہ علیہ وسلم کا بعثت — هو الذي بعث في الأمیین رسولا منهم یتلو علیهم آیاته و یزکیهم و یعلمهم الکتاب و الحکمة؛ و إن کانوا من قبل لفي ضلال مبین۔
۲۔ ’’هُوَ الَّذِي بَعَثَ فِي الْأُمِّیِّینَ رَسُولًا مِّنْهُمْ يَتْلُو عَلَيْهِمْ آيَاتِهِ وَيُزَكِّيهِمْ وَيُعَلِّمُهُمُ الْكِتَابَ وَالْحِكْمَۃَ وَإِن كَانُوا مِن قَبْلُ لَفِي ضَلَالٍ مُّبِينٍ‘‘ — وہی ہے جس نے ان پڑھوں میں انہیں میں سے ایک رسول اٹھایا — جو ان پر اس کی آیات پڑھتا ہے اور انہیں پاک کرتا ہے اور انہیں کتاب اور حکمت سکھاتا ہے — اگرچہ وہ اس سے پہلے کھلی گمراہی میں تھے — یعنی وہی ہے جس نے ان پڑھوں میں انہیں میں سے ایک رسول اٹھایا جو ان پر اس کی آیات پڑھتا ہے اور انہیں پاک کرتا ہے اور انہیں کتاب اور حکمت سکھاتا ہے اگرچہ وہ اس سے پہلے کھلی گمراہی میں تھے۔
۳۔ عملی سبق: رسول کی اطاعت کرو؛ اللہ سے ڈرو۔"""
),
5180: (
"اور ان میں سے دوسروں کو بھی جو ابھی انہیں سے نہیں ملے — اور وہ غالب حکمت والا ہے",
"""۱۔ بعد والے مسلمان — و آخرین منهم لما یلحقوا بهم؛ و هو العزیز الحکیم۔
۲۔ ’’وَآخَرِينَ مِنْهُمْ لَمَّا يَلْحَقُوا بِهِمْ وَهُوَ الْعَزِيزُ الْحَكِيمُ‘‘ — اور ان میں سے دوسروں کو بھی جو ابھی انہیں سے نہیں ملے — اور وہ غالب حکمت والا ہے — یعنی اور ان میں سے دوسروں کو بھی جو ابھی انہیں سے نہیں ملے اور وہ غالب حکمت والا ہے۔
۳۔ عملی سبق: اللہ کے دین کی تبلیغ کرو؛ اللہ سے ڈرو۔"""
),
5181: (
"یہ اللہ کا فضل ہے جو جسے چاہے دے — اور اللہ بہت بڑے فضل والا ہے",
"""۱۔ اللہ کا فضل — ذلک فضل الله یؤتیه من یشاء؛ و الله ذو الفضل العظیم۔
۲۔ ’’ذَٰلِكَ فَضْلُ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ‘‘ — یہ اللہ کا فضل ہے جو جسے چاہے دے — اور اللہ بہت بڑے فضل والا ہے — یعنی یہ اللہ کا فضل ہے جو جسے چاہے دے اور اللہ بہت بڑے فضل والا ہے۔
۳۔ عملی سبق: اللہ کے فضل کا شکر کرو؛ اللہ سے ڈرو۔"""
),
5182: (
"ان لوگوں کی مثال جنہیں تورات کا ذمہ دار بنایا گیا پھر انہوں نے اسے اٹھایا نہیں — جیسے گدھا کتابیں اٹھاتا ہے — بہت برا مثال ہے ان لوگوں کی جو اللہ کی آیات جھٹلاتے ہیں — اور اللہ ظالموں کی راہ نہیں دکھاتا",
"""۱۔ یہودیوں کی مثال — مثل الذین حُمّلوا التوراۃ ثم لم یحملوها کمثل الحمار یحمل أسفارًا؛ بئس مثل القوم الذین کذّبوا بآیات الله؛ و الله لا یهدي القوم الظالمین۔
۲۔ ’’مَثَلُ الَّذِينَ حُمِّلُوا التَّوْرَاۃَ ثُمَّ لَمْ يَحْمِلُوهَا كَمَثَلِ الْحِمَارِ يَحْمِلُ أَسْفَارًا بِئْسَ مَثَلُ الْقَوْمِ الَّذِينَ كَذَّبُوا بِآيَاتِ اللَّهِ وَاللَّهُ لَا يَهْدِي الْقَوْمَ الظَّالِمِينَ‘‘ — ان لوگوں کی مثال جنہیں تورات کا ذمہ دار بنایا گیا پھر انہوں نے اسے اٹھایا نہیں — جیسے گدھا کتابیں اٹھاتا ہے — بہت برا مثال ہے ان لوگوں کی جو اللہ کی آیات جھٹلاتے ہیں — اور اللہ ظالموں کی راہ نہیں دکھاتا — یعنی ان لوگوں کی مثال جنہیں تورات کا ذمہ دار بنایا گیا پھر انہوں نے اسے اٹھایا نہیں جیسے گدھا کتابیں اٹھاتا ہے بہت برا مثال ہے ان لوگوں کی جو اللہ کی آیات جھٹلاتے ہیں اور اللہ ظالموں کی راہ نہیں دکھاتا۔
۳۔ عملی سبق: کتاب اللہ پر عمل کرو؛ اللہ سے ڈرو۔"""
),
5183: (
"کہہ دے اے یہودیوں اگر تم گمان کرتے ہو کہ تم اللہ کے ولی ہو دوسروں سے الگ تو موت کی تمنا کرو اگر تم سچے ہو",
"""۱۔ یہودیوں کا دھوکا — قل یا أیها الذین هادوا إن زعمتم أنکم أولیاء لله من دون الناس فتمنّوا الموت إن کنتم صادقین۔
۲۔ ’’قُلْ يَا أَيُّهَا الَّذِينَ هَادُوا إِن زَعَمْتُمْ أَنَّكُمْ أَوْلِيَاءُ لِلَّهِ مِن دُونِ النَّاسِ فَتَمَنَّوُا الْمَوْتَ إِن كُنتُمْ صَادِقِينَ‘‘ — کہہ دے اے یہودیوں اگر تم گمان کرتے ہو کہ تم اللہ کے ولی ہو دوسروں سے الگ تو موت کی تمنا کرو اگر تم سچے ہو — یعنی کہہ دے اے یہودیوں اگر تم گمان کرتے ہو کہ تم اللہ کے ولی ہو دوسروں سے الگ تو موت کی تمنا کرو اگر تم سچے ہو۔
۳۔ عملی سبق: سچ بولو؛ اللہ سے ڈرو۔"""
),
5184: (
"اور وہ اسے کبھی تمنا نہیں کریں گے ان کاموں کی وجہ سے جو انہوں نے اپنے ہاتھوں سے آگے بھیجے — اور اللہ ظالموں کو جانتا ہے",
"""۱۔ ان کے اعمال — و لا یتمنّونه أبدًا بما قدّمت أیدیهم؛ و الله علیم بالظالمین۔
۲۔ ’’وَلَا يَتَمَنَّوْنَهُ أَبَدًا بِمَا قَدَّمَتْ أَيْدِيهِمْ وَاللَّهُ عَلِيمٌ بِالظَّالِمِينَ‘‘ — اور وہ اسے کبھی تمنا نہیں کریں گے ان کاموں کی وجہ سے جو انہوں نے اپنے ہاتھوں سے آگے بھیجے — اور اللہ ظالموں کو جانتا ہے — یعنی اور وہ اسے کبھی تمنا نہیں کریں گے ان کاموں کی وجہ سے جو انہوں نے اپنے ہاتھوں سے آگے بھیجے اور اللہ ظالموں کو جانتا ہے۔
۳۔ عملی سبق: نیک اعمال کرو؛ اللہ سے ڈرو۔"""
),
5185: (
"کہہ دے بے شک وہ موت جس سے تم بھاگتے ہو وہ تم سے ملے گی — پھر تم غیب اور ظاہر کے جاننے والے کی طرف لوٹائے جاؤ گے اور وہ تمہیں تمہارے اعمال بتائے گا",
"""۱۔ موت لازمی ہے — قل إن الموت الذي تفرّون منه فإنه ملاقیکم؛ ثم تردّون إلی عالم الغیب و الشهادۃ فینبئکم بما کنتم تعملون۔
۲۔ ’’قُلْ إِنَّ الْمَوْتَ الَّذِي تَفِرُّونَ مِنْهُ فَإِنَّهُ مُلَاقِيكُمْ ثُمَّ تُرَدُّونَ إِلَىٰ عَالِمِ الْغَيْبِ وَالشَّهَادَۃِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ‘‘ — کہہ دے بے شک وہ موت جس سے تم بھاگتے ہو وہ تم سے ملے گی — پھر تم غیب اور ظاہر کے جاننے والے کی طرف لوٹائے جاؤ گے اور وہ تمہیں تمہارے اعمال بتائے گا — یعنی کہہ دے بے شک وہ موت جس سے تم بھاگتے ہو وہ تم سے ملے گی پھر تم غیب اور ظاہر کے جاننے والے کی طرف لوٹائے جاؤ گے اور وہ تمہیں تمہارے اعمال بتائے گا۔
۳۔ عملی سبق: موت کی تیاری کرو؛ اللہ سے ڈرو۔"""
),
5186: (
"اے ایمان والو جب جمعہ کے دن نماز کے لیے بلایا جائے تو اللہ کے ذکر کی طرف دوڑو اور خرید و فروخت چھوڑ دو — یہ تمہارے لیے بہتر ہے اگر تم جانتے ہو",
"""۱۔ جمعہ کی نماز — یا أیها الذین آمنوا إذا نودي للصلاۃ من یوم الجمعۃ فاسعوا إلی ذکر الله و ذروا البیع؛ ذلکم خیر لکم إن کنتم تعلمون۔
۲۔ ’’يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا نُودِيَ لِلصَّلَاۃِ مِن يَوْمِ الْجُمُعَۃِ فَاسْعَوْا إِلَىٰ ذِكْرِ اللَّهِ وَذَرُوا الْبَيْعَ ذَٰلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ‘‘ — اے ایمان والو جب جمعہ کے دن نماز کے لیے بلایا جائے تو اللہ کے ذکر کی طرف دوڑو اور خرید و فروخت چھوڑ دو — یہ تمہارے لیے بہتر ہے اگر تم جانتے ہو — یعنی اے ایمان والو جب جمعہ کے دن نماز کے لیے بلایا جائے تو اللہ کے ذکر کی طرف دوڑو اور خرید و فروخت چھوڑ دو یہ تمہارے لیے بہتر ہے اگر تم جانتے ہو۔
۳۔ عملی سبق: جمعہ کی نماز پڑھو؛ اللہ سے ڈرو۔"""
),
5187: (
"پھر جب نماز پوری ہو جائے تو زمین میں منتشر ہو جاؤ اور اللہ کے فضل سے تلاش کرو — اور اللہ کو کثرت سے یاد کرو تاکہ تم کامیاب ہو",
"""۱۔ نماز کے بعد — فإذا قضیت الصلاۃ فانتشروا في الأرض و ابتغوا من فضل الله و اذکروا الله کثیرا لعلکم تفلحون۔
۲۔ ’’فَإِذَا قُضِيَتِ الصَّلَاۃُ فَانتَشِرُوا فِي الْأَرْضِ وَابْتَغُوا مِن فَضْلِ اللَّهِ وَاذْكُرُوا اللَّهَ كَثِيرًا لَّعَلَّكُمْ تُفْلِحُونَ‘‘ — پھر جب نماز پوری ہو جائے تو زمین میں منتشر ہو جاؤ اور اللہ کے فضل سے تلاش کرو — اور اللہ کو کثرت سے یاد کرو تاکہ تم کامیاب ہو — یعنی پھر جب نماز پوری ہو جائے تو زمین میں منتشر ہو جاؤ اور اللہ کے فضل سے تلاش کرو اور اللہ کو کثرت سے یاد کرو تاکہ تم کامیاب ہو۔
۳۔ عملی سبق: اللہ کا ذکر کرو؛ حلال کماؤ؛ اللہ سے ڈرو۔"""
),
5188: (
"اور جب وہ کوئی تجارت یا تماشا دیکھتے ہیں تو اس کی طرف دوڑ پڑتے ہیں اور تجھے کھڑا چھوڑ دیتے ہیں — کہہ دے جو اللہ کے پاس ہے وہ کھیل تماشے اور تجارت سے بہتر ہے — اور اللہ بہترین رزق دینے والا ہے",
"""۱۔ تجارت کا فتنہ — و إذا رأوا تجارة أو لهواً انفضّوا إلیها و ترکواک قائما؛ قل ما عند الله خیر من اللهو و من التجارة؛ و الله خیر الرازقین۔
۲۔ ’’وَإِذَا رَأَوْا تِجَارَۃً أَوْ لَهْوًا انْفَضُّوا إِلَيْهَا وَتَرَكُوكَ قَائِمًا قُلْ مَا عِنْدَ اللَّهِ خَيْرٌ مِنَ اللَّهْوِ وَمِنَ التِّجَارَۃِ وَاللَّهُ خَيْرُ الرَّازِقِينَ‘‘ — اور جب وہ کوئی تجارت یا تماشا دیکھتے ہیں تو اس کی طرف دوڑ پڑتے ہیں اور تجھے کھڑا چھوڑ دیتے ہیں — کہہ دے جو اللہ کے پاس ہے وہ کھیل تماشے اور تجارت سے بہتر ہے — اور اللہ بہترین رزق دینے والا ہے — یعنی اور جب وہ کوئی تجارت یا تماشا دیکھتے ہیں تو اس کی طرف دوڑ پڑتے ہیں اور تجھے کھڑا چھوڑ دیتے ہیں کہہ دے جو اللہ کے پاس ہے وہ کھیل تماشے اور تجارت سے بہتر ہے اور اللہ بہترین رزق دینے والا ہے۔
۳۔ عملی سبق: اللہ کو ترجیح دو؛ اللہ سے ڈرو۔"""
),
}
